def seed_full_producers(db_path="ergo_statements.db"):
    conn = sqlite3.connect(db_path)
    cur = conn.cursor()
    cur.execute('''
    CREATE TABLE IF NOT EXISTS producers_catalog (
        producer_code TEXT PRIMARY KEY,
        ergo_code TEXT,
        full_name TEXT NOT NULL,
        partner_type TEXT,
        partner_type_label TEXT,
        role TEXT,
        hierarchy TEXT,
        tier TEXT,
        manager TEXT,
        phone TEXT,
        email TEXT,
        address TEXT,
        nomos TEXT,
        comm_cat TEXT,
        status TEXT DEFAULT 'Ενεργός',
        commission_rate REAL DEFAULT 25.0,
        notes TEXT
    );
    ''')
    
    for col, ctype in [
        ('ergo_code', 'TEXT'),
        ('partner_type', 'TEXT'),
        ('partner_type_label', 'TEXT'),
        ('hierarchy', 'TEXT'),
        ('manager', 'TEXT'),
        ('address', 'TEXT'),
        ('nomos', 'TEXT'),
        ('comm_cat', 'TEXT')
    ]:
        try:
            cur.execute(f"ALTER TABLE producers_catalog ADD COLUMN {col} {ctype};")
        except Exception:
            pass
            
    cur.execute("DELETE FROM producers_catalog;")
    
    tuples = []
    for p in EMBEDDED_PRODUCERS:
        tuples.append((
            p.get('producer_code'),
            p.get('ergo_code') or '-',
            p.get('full_name') or p.get('producer_name'),
            p.get('partner_type') or 'DIRECT_AGENT',
            p.get('partner_type_label') or '🏢 Άμεσος Πράκτορας (Οργανωτική Ομάδα 40071)',
            p.get('role') or 'Ασφαλιστικός Πράκτορας',
            p.get('hierarchy') or 'ΠΑΡΑΓΩΓΟΣ',
            p.get('tier') or 'Οργανωτική Ομάδα (25% - 29%)',
            p.get('manager') or 'ΙΔΙΟΣ',
            p.get('phone') or '-',
            p.get('email') or '-',
            p.get('address') or '-',
            p.get('nomos') or '-',
            p.get('comm_cat') or '-',
            p.get('status') or 'Ενεργός',
            float(p.get('commission_rate') or p.get('avg_rate') or 25.0),
            p.get('notes') or 'LANCA & ERGO Registry'
        ))
        
    cur.executemany('''
        INSERT OR REPLACE INTO producers_catalog
        (producer_code, ergo_code, full_name, partner_type, partner_type_label, role, hierarchy, tier, manager, phone, email, address, nomos, comm_cat, status, commission_rate, notes)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?);
    ''', tuples)
    
    conn.commit()
    conn.close()
    print(f"Seeded {len(tuples)} producers into {db_path} successfully!")

if __name__ == "__main__":
    seed_full_producers("ergo_statements.db")
    seed_full_producers("lanca_ergo_local.db")
